1	package redact
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"fmt"
8		"io"
9		"math"
10		"net/url"
11		"regexp"
12		"sort"
13		"strings"
14		"sync"
15		"time"
16	
17		"github.com/betterleaks/betterleaks/detect"
18	)
19	
20	// secretPattern matches high-entropy strings that may be secrets.
21	// Note: / is excluded to prevent matching entire file paths as single tokens.
22	// Base64 and JWT tokens are still caught via high-entropy segments between slashes.
23	var secretPattern = regexp.MustCompile(`[A-Za-z0-9+_=-]{10,}`)
24	
25	// credentialedURIPattern matches URLs that embed userinfo with a password, such
26	// as REDACTED or REDACTED These often have
27	// moderate entropy and are not reliably covered by vendor-specific scanners.
28	var credentialedURIPattern = regexp.MustCompile(`(?i)\b[a-z][a-z0-9+.-]{1,31}://[^\s/?#@"'` + "`" + `<>:]*:[^\s/?#@"'` + "`" + `<>]+@[^\s"'` + "`" + `<>]+`)
29	
30	// dbPasswordKeyShape matches a DB-prefixed credential key (vendor prefix +
31	// optional `_word`/`-word` segments + `password`/`passwd`/`pwd`). Used to
32	// compose both the env-var assignment regex and the JSON-key regex so the
33	// vendor list stays in one place.
34	const dbPasswordKeyShape = `(?:db|database|pg|postgres|postgresql|mysql|mariadb|redis|mongo|mongodb|sqlserver|mssql|jdbc)(?:[_-]+[a-z0-9]+)*[_-]*(?:password|passwd|pwd)` //nolint:gosec // regex literal, not a credential
35	
36	var (
37		jdbcPattern          = regexp.MustCompile(`(?i)\bjdbc:[^\s"'<>` + "`" + `]+`)
38		databaseURLPattern   = regexp.MustCompile(`(?i)\b(?:postgres(?:ql)?|mysql|mariadb|mongodb(?:\+srv)?|redis)://[^\s"'<>` + "`" + `]+`)
39		keywordDSNPattern    = regexp.MustCompile(`(?i)\b[a-z_][a-z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s"']+)(?:\s+[a-z_][a-z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s"']+)){2,}`)
40		semicolonConnPattern = regexp.MustCompile(`(?i)\b[a-z][a-z0-9 _-]*=(?:\{[^}]*\}|"[^"]*"|'[^']*'|[^=;"'\s]+)(?:;[a-z][a-z0-9 _-]*=(?:\{[^}]*\}|"[^"]*"|'[^']*'|[^=;"'\s]+)){2,}`)
41		// credentialValuePattern requires the prefix to start at a non-alphanumeric
42		// boundary, so APP_DB_PASSWORD matches via the leading `_` but mydbpassword
43		// does not.
44		credentialValuePattern = regexp.MustCompile(`(?i)(?:^|[^A-Za-z0-9])(` + dbPasswordKeyShape + `)\s*=\s*("[^"]*"|'[^']*'|[^\s,;&]+)`)
45	
46		keywordHostPattern      = regexp.MustCompile(`(?i)(?:^|\s)host=`)
47		keywordUserPattern      = regexp.MustCompile(`(?i)(?:^|\s)user=`)
48		semicolonServerPattern  = regexp.MustCompile(`(?i)(?:^|;)\s*(?:server|data source|datasource|addr|address|network address)\s*=`)
49		semicolonUserPattern    = regexp.MustCompile(`(?i)(?:^|;)\s*(?:user id|userid|user|uid)\s*=`)
50		passwordAssignmentRegex = regexp.MustCompile(`(?i)(?:^|[?&;\s])(?:password|pwd)=("[^"]*"|'[^']*'|[^&;\s"']+)`)
51		// credentialJSONKeyRegex operates on output of normalizeCredentialJSONKey
52		// (already lowercased, `-`/` `/`.` → `_`), so the `(?i)` flag is unnecessary.
53		credentialJSONKeyRegex  = regexp.MustCompile(`^` + dbPasswordKeyShape + `$`)
54		genericPasswordKeyRegex = regexp.MustCompile(`(?i)^(?:password|passwd|pwd)$`)
55	)
56	
57	// entropyThreshold is the minimum Shannon entropy for a string to be considered
58	// a secret. 4.5 was chosen through trial and error: high enough to avoid false
59	// positives on common words and identifiers, low enough to catch typical API keys
60	// and tokens which tend to have entropy well above 5.0.
61	const entropyThreshold = 4.5
62	
63	// RedactedPlaceholder is the replacement text used for redacted secrets.
64	const RedactedPlaceholder = "REDACTED"
65	
66	// placeholderSecretValues lists lowercase values that should be treated as
67	// non-secrets when they appear as a credential value: prior redactions
68	// (REDACTED / [REDACTED] / <REDACTED>), common documentation placeholders,
69	// and obviously-non-real defaults. Values matched by shape (mask runs,
70	// `<…>` brackets, `${…}` shell expansion) are handled separately.
71	var placeholderSecretValues = func() map[string]struct{} {
72		lower := strings.ToLower(RedactedPlaceholder)
73		values := []string{
74			lower, "[" + lower + "]", "<" + lower + ">",
75			"changeme", "example", "placeholder",
76			"your_password", "your_db_password", "your_secret",
77			"secret_here",
78		}
79		out := make(map[string]struct{}, len(values))
80		for _, v := range values {
81			out[v] = struct{}{}
82		}
83		return out
84	}()
85	
86	// RedactedBytes represents transcript data that has been through secret
87	// redaction. Consumers that require pre-redacted input (e.g., compact.Compact,
88	// checkpoint stores) accept this type to enforce the contract at compile time.
89	//
90	// Produced by JSONLBytes (primary constructor) or trusted wrappers for data
91	// previously persisted by checkpoint writers.
92	type RedactedBytes struct {
93		data []byte
94	}
95	
96	// Bytes returns the underlying byte slice.
97	func (r RedactedBytes) Bytes() []byte {
98		return r.data
99	}
100	
101	// Len returns the number of bytes in the redacted payload.
102	func (r RedactedBytes) Len() int {
103		return len(r.data)
104	}
105	
106	// AlreadyRedacted wraps transcript bytes known to already be redacted by a
107	// prior write path. Use this ONLY for trusted sources such as persisted
108	// checkpoint transcripts or controlled test fixtures. For fresh transcript
109	// input, use JSONLBytes.
110	func AlreadyRedacted(data []byte) RedactedBytes {
111		return RedactedBytes{data: data}
112	}
113	
114	var (
115		betterleaksDetector     *detect.Detector
116		betterleaksDetectorOnce sync.Once
117	)
118	
119	func getDetector() *detect.Detector {
120		betterleaksDetectorOnce.Do(func() {
121			d, err := detect.NewDetectorDefaultConfig()
122			if err != nil {
123				return
124			}
125			betterleaksDetector = d
126		})
127		return betterleaksDetector
128	}
129	
130	// region represents a byte range to redact.
131	type region struct{ start, end int }
132	
133	// taggedRegion extends region with a label for typed replacement tokens.
134	// Empty label = secret (produces "REDACTED"). Non-empty = PII (produces "[REDACTED_<LABEL>]").
135	type taggedRegion struct {
136		region
137	
138		label string
139	}
140	
141	type jsonReplacement struct {
142		key      string
143		original string
144		redacted string
145	}
146	
147	type connectionStringRule struct {
148		pattern   *regexp.Regexp
149		hasSecret func(string) bool
150	}
151	
152	var connectionStringRules = []connectionStringRule{
153		{pattern: jdbcPattern, hasSecret: hasJDBCPassword},
154		{pattern: databaseURLPattern, hasSecret: hasDatabaseURLSecret},
155		{pattern: keywordDSNPattern, hasSecret: hasKeywordDSNPassword},
156		{pattern: semicolonConnPattern, hasSecret: hasSemicolonConnectionPassword},
157	}
158	
159	// String replaces secrets and PII in s using layered detection:
160	//  1. Entropy-based: high-entropy alphanumeric sequences (threshold 4.5)
161	//  2. Pattern-based: betterleaks regex rules (260+ known secret formats)
162	//  3. Provider token prefixes: deterministic prefix rules for credential
163	//     formats betterleaks misses in isolation (e.g. Supabase sb_secret_)
164	//  4. Credentialed URIs: URLs containing userinfo passwords
165	//  5. Database connection strings: JDBC, keyword DSNs, and semicolon strings
166	//  6. User-defined custom rules: configured via ConfigureCustomRules
167	//  7. Bounded credential key/value pairs: DB_PASSWORD=...
168	//  8. PII detection: email, phone, address patterns (only when configured via ConfigurePII)
169	//
170	// A string is redacted if ANY method flags it.
171	func String(s string) string {
172		return applyRegions(s, detectAllLayers(s))
173	}
174	
175	// detectAllLayers runs the eight always-on/opt-in regex-based redaction
176	// layers and returns their tagged regions. The OpenAI Privacy Filter
177	// (the final, network-backed layer) is NOT included — callers that want it
178	// append detectOPF spans to the result before passing to applyRegions. See
179	// StringWithPrivacyFilter for the augmented flow.
180	func detectAllLayers(s string) []taggedRegion {
181		var regions []taggedRegion
182	
183		// 1. Entropy-based detection (secrets — always on).
184		for _, loc := range secretPattern.FindAllStringIndex(s, -1) {
185			start, end := loc[0], loc[1]
186	
187			// Don't consume characters that are part of JSON/string escape sequences.
188			// Example: in "controller.go\nmodel.go", the regex could match "nmodel"
189			// (consuming the 'n' from '\n'), and after replacement the '\' would be
190			// followed by 'R' from "REDACTED", creating invalid escape '\R'.
191			// Only skip for known JSON escape letters to avoid trimming real secrets
192			// that happen to follow a literal backslash in decoded content.
193			if start > 0 && s[start-1] == '\\' {
194				switch s[start] {
195				case 'n', 't', 'r', 'b', 'f', 'u', '"', '\\', '/':
196					start++
197					if end-start < 10 {
198						continue
199					}
200				}
201			}
202	
203			if shannonEntropy(s[start:end]) > entropyThreshold {
204				regions = append(regions, taggedRegion{region: region{start, end}})
205			}
206		}
207	
208		// 2. Pattern-based detection via betterleaks (secrets — always on).
209		if d := getDetector(); d != nil {
210			for _, f := range d.DetectString(s) {
211				if f.Secret == "" {
212					continue
213				}
214				searchFrom := 0
215				for {
216					idx := strings.Index(s[searchFrom:], f.Secret)
217					if idx < 0 {
218						break
219					}
220					absIdx := searchFrom + idx
221					regions = append(regions, taggedRegion{region: region{absIdx, absIdx + len(f.Secret)}})
222					searchFrom = absIdx + len(f.Secret)
223				}
224			}
225		}
226	
227		// 3. Provider-specific deterministic token prefixes (secrets — always on).
228		// Catches low-entropy credential formats (e.g. Supabase sb_secret_) that
229		// the entropy and betterleaks layers miss when captured in isolation.
230		regions = append(regions, detectProviderTokens(s)...)
231	
232		// 4. Credentialed URIs (secrets — always on).
233		for _, loc := range credentialedURIPattern.FindAllStringIndex(s, -1) {
234			regions = append(regions, taggedRegion{region: region{loc[0], loc[1]}})
235		}
236	
237		// 5. Database and connection-string detection (secrets — always on).
238		regions = append(regions, detectConnectionStrings(s)...)
239	
240		// 6. User-defined custom rules (secrets — only runs when configured).
241		regions = append(regions, detectCustomRules(getCustomRulesConfig(), s)...)
242	
243		// 7. Bounded credential key/value detection (secrets — always on).
244		regions = append(regions, detectCredentialValues(s)...)
245	
246		// 8. PII detection (opt-in — only runs when configured).
247		regions = append(regions, detectPII(getPIIConfig(), s)...)
248	
249		return regions
250	}
251	
252	// applyRegions sorts, merges, and replaces the given regions in s, returning
253	// the redacted string. Returns s unchanged when regions is empty.
254	func applyRegions(s string, regions []taggedRegion) string {
255		if len(regions) == 0 {
256			return s
257		}
258	
259		sort.Slice(regions, func(i, j int) bool {
260			if regions[i].start != regions[j].start {
261				return regions[i].start < regions[j].start
262			}
263			if regions[i].end != regions[j].end {
264				return regions[i].end > regions[j].end // larger region first
265			}
266			return regions[i].label < regions[j].label // deterministic tie-break
267		})
268		merged := []taggedRegion{regions[0]}
269		for _, r := range regions[1:] {
270			last := &merged[len(merged)-1]
271			if r.start <= last.end {
272				if r.end > last.end {
273					last.end = r.end
274				}
275				// Keep the existing label (first/larger region wins)
276			} else {
277				merged = append(merged, r)
278			}
279		}
280	
281		var b strings.Builder
282		prev := 0
283		for _, r := range merged {
284			b.WriteString(s[prev:r.start])
285			b.WriteString(replacementToken(r.label))
286			prev = r.end
287		}
288		b.WriteString(s[prev:])
289		return b.String()
290	}
291	
292	func detectConnectionStrings(s string) []taggedRegion {
293		if !strings.ContainsRune(s, '=') {
294			return nil
295		}
296		var regions []taggedRegion
297		for _, rule := range connectionStringRules {
298			regions = append(regions, detectConnectionStringRule(s, rule)...)
299		}
300		return regions
301	}
302	
303	func detectConnectionStringRule(s string, rule connectionStringRule) []taggedRegion {
304		var regions []taggedRegion
305		for _, loc := range rule.pattern.FindAllStringIndex(s, -1) {
306			start, end := loc[0], trimConnectionStringEnd(s, loc[0], loc[1])
307			if start >= end {
308				continue
309			}
310			if rule.hasSecret(s[start:end]) {
311				regions = append(regions, taggedRegion{region: region{start, end}})
312			}
313		}
314		return regions
315	}
316	
317	func trimConnectionStringEnd(s string, start, end int) int {
318		for end > start {
319			switch s[end-1] {
320			case '.', ',', ';', ':', '!', '?', ')', ']':
321				end--
322			default:
323				return end
324			}
325		}
326		return end
327	}
328	
329	func hasJDBCPassword(candidate string) bool {
330		if !strings.HasPrefix(strings.ToLower(candidate), "jdbc:") {
331			return false
332		}
333		return hasNonPlaceholderPasswordAssignment(candidate)
334	}
335	
336	func hasDatabaseURLSecret(candidate string) bool {
337		u, err := url.Parse(candidate)
338		if err != nil || u.Scheme == "" || u.Host == "" {
339			return false
340		}
341		for key, values := range u.Query() {
342			if !isPasswordQueryKey(key) {
343				continue
344			}
345			for _, value := range values {
346				if hasNonPlaceholderPasswordValue(value) {
347					return true
348				}
349			}
350		}
351		return false
352	}
353	
354	func isPasswordQueryKey(key string) bool {
355		return strings.EqualFold(key, "password") || strings.EqualFold(key, "pwd")
356	}
357	
358	func hasKeywordDSNPassword(candidate string) bool {
359		return keywordHostPattern.MatchString(candidate) &&
360			keywordUserPattern.MatchString(candidate) &&
361			hasNonPlaceholderPasswordAssignment(candidate)
362	}
363	
364	func hasSemicolonConnectionPassword(candidate string) bool {
365		return semicolonServerPattern.MatchString(candidate) &&
366			semicolonUserPattern.MatchString(candidate) &&
367			hasNonPlaceholderPasswordAssignment(candidate)
368	}
369	
370	func detectCredentialValues(s string) []taggedRegion {
371		var regions []taggedRegion
372		for _, loc := range credentialValuePattern.FindAllStringSubmatchIndex(s, -1) {
373			if len(loc) < 6 || loc[4] < 0 || loc[5] < 0 {
374				continue
375			}
376			start, end := unquoteRange(s, loc[4], loc[5])
377			if hasNonPlaceholderPasswordValue(s[start:end]) {
378				regions = append(regions, taggedRegion{region: region{start, end}})
379			}
380		}
381		return regions
382	}
383	
384	func unquoteRange(s string, start, end int) (int, int) {
385		if end-start < 2 {
386			return start, end
387		}
388		first, last := s[start], s[end-1]
389		if (first == '"' && last == '"') || (first == '\'' && last == '\'') {
390			return start + 1, end - 1
391		}
392		return start, end
393	}
394	
395	func hasNonPlaceholderPasswordAssignment(candidate string) bool {
396		for _, loc := range passwordAssignmentRegex.FindAllStringSubmatchIndex(candidate, -1) {
397			if len(loc) >= 4 && loc[2] >= 0 && loc[3] >= 0 {
398				start, end := unquoteRange(candidate, loc[2], loc[3])
399				if hasNonPlaceholderPasswordValue(candidate[start:end]) {
400					return true
401				}
402			}
403		}
404		return false
405	}
406	
407	func hasNonPlaceholderPasswordValue(value string) bool {
408		return value != "" && !isPlaceholderSecretValue(value)
409	}
410	
411	func isPlaceholderSecretValue(value string) bool {
412		trimmed := strings.Trim(strings.TrimSpace(value), `"'`)
413		if trimmed == "" {
414			return true
415		}
416		if isBracketedPlaceholder(trimmed) {
417			return true
418		}
419		normalized := strings.ToLower(trimmed)
420		if strings.HasPrefix(normalized, "${") && strings.HasSuffix(normalized, "}") {
421			return true
422		}
423		if _, ok := placeholderSecretValues[normalized]; ok {
424			return true
425		}
426		return isRepeatedCharPlaceholder(normalized)
427	}
428	
429	// bracketedPlaceholderInteriorRE matches the inside of a "<…>" placeholder
430	// shape: lowercase letters joined by `-` or `_`. Digits, mixed case, and
431	// special chars are rejected so values like `<hunter2>` or `<RealPassword>`
432	// still fall through to redaction.
433	var bracketedPlaceholderInteriorRE = regexp.MustCompile(`^[a-z][a-z_-]*$`)
434	
435	// isBracketedPlaceholder reports whether s is a "<name>" doc placeholder
436	// (e.g. "<password>", "<your-db-password>"). The minimum total length of 5
437	// keeps this from firing on `<a>` / `<ab>`.
438	func isBracketedPlaceholder(s string) bool {
439		if len(s) < 5 || s[0] != '<' || s[len(s)-1] != '>' {
440			return false
441		}
442		return bracketedPlaceholderInteriorRE.MatchString(s[1 : len(s)-1])
443	}
444	
445	// isRepeatedCharPlaceholder reports whether s is a run of a single masking
446	// character commonly used to redact values in docs and screenshots, e.g.
447	// "***", "xxxx", "....", "----". The minimum length of 3 keeps single-char
448	// or 2-char values like `x` or `**` from being treated as masks.
449	func isRepeatedCharPlaceholder(s string) bool {
450		if len(s) < 3 {
451			return false
452		}
453		first := s[0]
454		switch first {
455		case '*', 'x', '.', '-':
456		default:
457			return false
458		}
459		for i := 1; i < len(s); i++ {
460			if s[i] != first {
461				return false
462			}
463		}
464		return true
465	}
466	
467	func isCredentialJSONSecretKey(key string, credentialContext bool) bool {
468		normalized := normalizeCredentialJSONKey(key)
469		if credentialJSONKeyRegex.MatchString(normalized) {
470			return true
471		}
472		return credentialContext && genericPasswordKeyRegex.MatchString(normalized)
473	}
474	
475	func isCredentialJSONObject(obj map[string]any) bool {
476		var hasHost, hasUser bool
477		for key := range obj {
478			switch normalizeCredentialJSONKey(key) {
479			case "host", "hostname", "server", "addr", "address", "datasource", "data_source":
480				hasHost = true
481			case "user", "username", "userid", "user_id", "uid":
482				hasUser = true
483			}
484			if hasHost && hasUser {
485				return true
486			}
487		}
488		return false
489	}
490	
491	func normalizeCredentialJSONKey(key string) string {
492		key = strings.ToLower(strings.TrimSpace(key))
493		key = strings.ReplaceAll(key, "-", "_")
494		key = strings.ReplaceAll(key, " ", "_")
495		// Flattened-config exporters (Spring, dotnet, Hashicorp Vault) emit dotted keys
496		// like "db.password" or "mysql.root.password"; treat them like underscored.
497		key = strings.ReplaceAll(key, ".", "_")
498		return key
499	}
500	
501	// Bytes is a convenience wrapper around String for []byte content.
502	func Bytes(b []byte) []byte {
503		s := string(b)
504		redacted := String(s)
505		if redacted == s {
506			return b
507		}
508		return []byte(redacted)
509	}
510	
511	// JSONLBytes redacts secrets in JSONL-formatted byte content and returns
512	// the result as RedactedBytes, certifying the output has been through redaction.
513	func JSONLBytes(b []byte) (RedactedBytes, error) {
514		s := string(b)
515		redacted, err := JSONLContent(s)
516		if err != nil {
517			return RedactedBytes{}, err
518		}
519		if redacted == s {
520			return RedactedBytes{data: b}, nil
521		}
522		return RedactedBytes{data: []byte(redacted)}, nil
523	}
524	
525	// JSONLBytesWithPrivacyFilter augments JSONLBytes with the OpenAI Privacy
526	// Filter. Use only at condensation/export boundaries; per-turn writes must
527	// use JSONLBytes.
528	func JSONLBytesWithPrivacyFilter(ctx context.Context, b []byte) (RedactedBytes, error) {
529		s := string(b)
530		redacted, err := JSONLContentWithPrivacyFilter(ctx, s)
531		if err != nil {
532			return RedactedBytes{}, err
533		}
534		if redacted == s {
535			return RedactedBytes{data: b}, nil
536		}
537		return RedactedBytes{data: []byte(redacted)}, nil
538	}
539	
540	// BytesWithPrivacyFilter augments Bytes with the OpenAI Privacy Filter for
541	// raw (non-JSONL) byte content. Used by checkpoint write paths that handle
542	// metadata files which may or may not be JSONL.
543	func BytesWithPrivacyFilter(ctx context.Context, b []byte) []byte {
544		s := string(b)
545		redacted := StringWithPrivacyFilter(ctx, s)
546		if redacted == s {
547			return b
548		}
549		return []byte(redacted)
550	}
551	
552	// JSONLContent parses each line as JSON to determine which string values
553	// need redaction, then performs targeted replacements on the raw JSON bytes.
554	// Lines with no secrets are returned unchanged, preserving original formatting.
555	//
556	// For multi-line JSON content (e.g., pretty-printed single JSON objects like
557	// OpenCode export), the function first attempts to parse the entire content as
558	// a single JSON value. This ensures field-aware redaction (which skips ID fields)
559	// is used instead of falling back to entropy-based detection on raw text lines,
560	// which would corrupt high-entropy identifiers.
561	func JSONLContent(content string) (string, error) {
562		return jsonlContentImpl(content, String)
563	}
564	
565	// jsonlContentImpl is the body of JSONLContent parameterized by a per-leaf
566	// redactor. JSONLContent passes String (regex layers only). The OPF-enabled
567	// flow uses two passes: one with a collector that records leaves and returns
568	// identity, one with a redactor that combines regex layers with cached OPF
569	// spans for the recorded leaves.
570	func jsonlContentImpl(content string, redactor func(string) string) (string, error) {
571		// Try parsing the entire content as a single JSON value first.
572		// Uses a streaming decoder to avoid copying the full content into []byte.
573		// After decoding, attempts a second Decode to confirm EOF — if it succeeds,
574		// the content is JSONL (multiple values) and we fall through to line-by-line.
575		trimmed := strings.TrimSpace(content)
576		if len(trimmed) > 0 {
577			dec := json.NewDecoder(strings.NewReader(trimmed))
578			var parsed any
579			if err := dec.Decode(&parsed); err == nil && isSingleJSONValue(dec) {
580				// Content is a single JSON value (object/array) — redact field-aware.
581				result, err := applyJSONReplacements(content, collectJSONLReplacements(parsed, redactor))
582				if err != nil {
583					return "", err
584				}
585				return result, nil
586			}
587		}
588	
589		// Fall back to line-by-line JSONL processing.
590		lines := strings.Split(content, "\n")
591		var b strings.Builder
592		for i, line := range lines {
593			if i > 0 {
594				b.WriteByte('\n')
595			}
596			lineTrimmed := strings.TrimSpace(line)
597			if lineTrimmed == "" {
598				b.WriteString(line)
599				continue
600			}
601			var parsed any
602			if err := json.Unmarshal([]byte(lineTrimmed), &parsed); err != nil {
603				b.WriteString(redactor(line))
604				continue
605			}
606			result, err := applyJSONReplacements(line, collectJSONLReplacements(parsed, redactor))
607			if err != nil {
608				return "", err
609			}
610			b.WriteString(result)
611		}
612		return b.String(), nil
613	}
614	
615	// StringWithPrivacyFilter augments String with the OpenAI Privacy Filter.
616	// Use only at condensation/export boundaries; per-turn writes must use
617	// String to avoid the OPF shell-out cost inside the agent loop.
618	func StringWithPrivacyFilter(ctx context.Context, s string) string {
619		regions := detectAllLayers(s)
620		regions = append(regions, detectOPF(ctx, getOPFConfig(), s)...)
621		return applyRegions(s, regions)
622	}
623	
624	// JSONLContentWithPrivacyFilter augments JSONLContent with the OpenAI
625	// Privacy Filter via batched inference. Walks the content twice: pass 1
626	// collects unique prose-shaped leaves into a single RedactBatch call;
627	// pass 2 applies the eight regex layers per leaf plus the cached OPF spans
628	// for that leaf. One OPF shell-out covers the whole transcript instead of
629	// one per leaf — without batching, a typical 500-leaf transcript would
630	// take many minutes per commit.
631	//
632	// Falls back to the plain JSONLContent flow when OPF is unconfigured, the
633	// breaker is tripped, no categories are enabled, or the batch call errors.
634	func JSONLContentWithPrivacyFilter(ctx context.Context, content string) (string, error) {
635		cfg := getOPFConfig()
636		if cfg == nil || !cfg.Enabled || cfg.runtime == nil || opfBreakerTripped.Load() {
637			return jsonlContentImpl(content, String)
638		}
639		cats := enabledCategories(cfg)
640		if len(cats) == 0 {
641			return jsonlContentImpl(content, String)
642		}
643	
644		// Pass 1: collect eligible (has-space, deduped) leaves. The collector
645		// closure returns identity so the JSONL walker doesn't mutate content.
646		seen := make(map[string]struct{})
647		var inputs []string
648		if _, err := jsonlContentImpl(content, func(v string) string {
649			if strings.ContainsRune(v, ' ') {
650				if _, ok := seen[v]; !ok {
651					seen[v] = struct{}{}
652					inputs = append(inputs, v)
653				}
654			}
655			return v
656		}); err != nil {
657			return "", err
658		}
659	
660		// Pass 2: single batched OPF call.
661		spansByInput := make(map[string][]Span, len(inputs))
662		if len(inputs) > 0 {
663			fmt.Fprintln(opfStderr, "→ OpenAI Privacy Filter: scanning transcript…")
664			start := time.Now()
665			batched, err := cfg.runtime.RedactBatch(ctx, inputs, cats)
666			if err != nil {
667				handleOPFFailure(ctx, cfg, err)
668				return jsonlContentImpl(content, String)
669			}
670			fmt.Fprintf(opfStderr, "✓ OpenAI Privacy Filter: done (%.1fs)\n", time.Since(start).Seconds())
671			// A short return means the runtime gave us fewer span slices than
672			// inputs — the tail leaves would receive zero OPF spans and the
673			// caller would proceed as if OPF had found nothing. That silently
674			// produces under-redacted output and is indistinguishable from a
675			// "no PII present" result. Treat as a runtime contract violation:
676			// trip the breaker so the pre-push rewrite's post-loop
677			// OPFBreakerTripped() check aborts before the Entire-OPF-Applied
678			// trailer can be attached to under-redacted commits. The production
679			// shell-out always returns len(inputs), so this only fires for a
680			// misbehaving custom runtime — but the cost of leaving it dormant
681			// is too high for a privacy contract.
682			if len(batched) != len(inputs) {
683				shortErr := fmt.Errorf("opf runtime returned %d span slices for %d inputs", len(batched), len(inputs))
684				handleOPFFailure(ctx, cfg, shortErr)
685				return jsonlContentImpl(content, String)
686			}
687			for i, in := range inputs {
688				spansByInput[in] = batched[i]
689			}
690		}
691	
692		// Pass 3: per-leaf regex layers + cached OPF spans.
693		return jsonlContentImpl(content, func(v string) string {
694			regions := detectAllLayers(v)
695			regions = append(regions, opfSpanRegions(v, spansByInput[v], cfg)...)
696			return applyRegions(v, regions)
697		})
698	}
699	
700	// applyJSONReplacements applies collected (original, redacted) string pairs
701	// to the raw JSON text, replacing JSON-encoded originals with their redacted forms.
702	// Returns s unchanged if repls is empty.
703	func applyJSONReplacements(s string, repls []jsonReplacement) (string, error) {
704		if len(repls) == 0 {
705			return s, nil
706		}
707		for _, r := range repls {
708			origJSON, err := jsonEncodeString(r.original)
709			if err != nil {
710				return "", err
711			}
712			replJSON, err := jsonEncodeString(r.redacted)
713			if err != nil {
714				return "", err
715			}
716			if r.key == "" {
717				s = strings.ReplaceAll(s, origJSON, replJSON)
718				continue
719			}
720			keyJSON, err := jsonEncodeString(r.key)
721			if err != nil {
722				return "", err
723			}
724			s = replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON)
725		}
726		return s, nil
727	}
728	
729	// replaceKeyedJSONValue replaces every occurrence of origJSON that follows
730	// keyJSON + optional whitespace + ':' + optional whitespace. Restricts
731	// substitution to value positions so a key's own redacted text is not
732	// rewritten when it collides with another field's value.
733	func replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON string) string {
734		if !strings.Contains(s, keyJSON) {
735			return s
736		}
737		var b strings.Builder
738		b.Grow(len(s))
739		i := 0
740		for i < len(s) {
741			j := strings.Index(s[i:], keyJSON)
742			if j < 0 {
743				b.WriteString(s[i:])
744				break
745			}
746			keyEnd := i + j + len(keyJSON)
747			b.WriteString(s[i : i+j])
748			b.WriteString(keyJSON)
749			p := keyEnd
750			for p < len(s) && isJSONWhitespace(s[p]) {
751				p++
752			}
753			if p >= len(s) || s[p] != ':' {
754				i = keyEnd
755				continue
756			}
757			p++
758			for p < len(s) && isJSONWhitespace(s[p]) {
759				p++
760			}
761			if p+len(origJSON) <= len(s) && s[p:p+len(origJSON)] == origJSON {
762				b.WriteString(s[keyEnd:p])
763				b.WriteString(replJSON)
764				i = p + len(origJSON)
765				continue
766			}
767			i = keyEnd
768		}
769		return b.String()
770	}
771	
772	func isJSONWhitespace(c byte) bool {
773		return c == ' ' || c == '\t' || c == '\n' || c == '\r'
774	}
775	
776	// isSingleJSONValue returns true if the decoder has reached EOF (no more
777	// top-level values). This distinguishes a single JSON value (e.g., pretty-printed
778	// object) from JSONL (multiple concatenated values). We attempt a second Decode
779	// and require io.EOF rather than relying on dec.More(), which is documented for
780	// use inside arrays/objects and not for top-level value boundaries.
781	func isSingleJSONValue(dec *json.Decoder) bool {
782		var discard json.RawMessage
783		return dec.Decode(&discard) == io.EOF
784	}
785	
786	// collectJSONLReplacements walks a parsed JSON value and collects unique
787	// string replacements via the supplied per-leaf redactor. JSONLContent
788	// passes String; the OPF-enabled flow passes a closure that combines the
789	// regex layers with cached batched OPF spans.
790	func collectJSONLReplacements(v any, redactor func(string) string) []jsonReplacement {
791		seen := make(map[string]bool)
792		var repls []jsonReplacement
793		var walk func(key string, credentialContext bool, v any)
794		walk = func(key string, credentialContext bool, v any) {
795			switch val := v.(type) {
796			case map[string]any:
797				if shouldSkipJSONLObject(val) {
798					return
799				}
800				childCredentialContext := credentialContext || isCredentialJSONObject(val)
801				for k, child := range val {
802					if shouldSkipJSONLField(k) {
803						continue
804					}
805					walk(k, childCredentialContext, child)
806				}
807			case []any:
808				for _, child := range val {
809					walk("", credentialContext, child)
810				}
811			case string:
812				redacted := redactor(val)
813				if redacted == val && isCredentialJSONSecretKey(key, credentialContext) && hasNonPlaceholderPasswordValue(val) {
814					redacted = RedactedPlaceholder
815				}
816				if redacted != val {
817					seenKey := key + "\x00" + val
818					if !seen[seenKey] {
819						seen[seenKey] = true
820						repls = append(repls, jsonReplacement{key: key, original: val, redacted: redacted})
821					}
822				}
823			}
824		}
825		walk("", false, v)
826		return repls
827	}
828	
829	// shouldSkipJSONLField returns true if a JSON key should be excluded from scanning/redaction.
830	// Skips signature fields (any key ending in "signature"), ID fields (ending in "id"/"ids"),
831	// and common path/directory fields.
832	func shouldSkipJSONLField(key string) bool {
833		lower := strings.ToLower(key)
834	
835		// Skip signature fields: cryptographic attestations, not secrets. Covers
836		// "signature" (Claude Code) and provider variants like "thinkingSignature"
837		// (Oh My Pi). Their values are high-entropy base64, so the entropy scanner
838		// would otherwise redact them — corrupting extended-thinking signatures and
839		// breaking transcript replay ("Invalid `signature` in `thinking` block").
840		if strings.HasSuffix(lower, "signature") {
841			return true
842		}
843	
844		// Skip ID fields
845		if strings.HasSuffix(lower, "id") || strings.HasSuffix(lower, "ids") {
846			return true
847		}
848	
849		// Skip common path and directory fields from agent transcripts.
850		// These appear frequently in tool calls and are structural, not secrets.
851		switch lower {
852		case "filepath", "file_path", "cwd", "root", "directory", "dir", "path":
853			return true
854		}
855	
856		return false
857	}
858	
859	// shouldSkipJSONLObject returns true if the object has "type":"image" or "type":"image_url".
860	func shouldSkipJSONLObject(obj map[string]any) bool {
861		t, ok := obj["type"].(string)
862		return ok && (strings.HasPrefix(t, "image") || t == "base64")
863	}
864	
865	func shannonEntropy(s string) float64 {
866		if len(s) == 0 {
867			return 0
868		}
869		freq := make(map[byte]int)
870		for i := range len(s) {
871			freq[s[i]]++
872		}
873		length := float64(len(s))
874		var entropy float64
875		for _, count := range freq {
876			p := float64(count) / length
877			entropy -= p * math.Log2(p)
878		}
879		return entropy
880	}
881	
882	// jsonEncodeString returns the JSON encoding of s without HTML escaping.
883	func jsonEncodeString(s string) (string, error) {
884		var buf bytes.Buffer
885		enc := json.NewEncoder(&buf)
886		enc.SetEscapeHTML(false)
887		if err := enc.Encode(s); err != nil {
888			return "", fmt.Errorf("json encode string: %w", err)
889		}
890		return strings.TrimSuffix(buf.String(), "\n"), nil
891	}
