	"os"
	"testing"

	bldetect "github.com/betterleaks/betterleaks/detect"
	"github.com/entireio/cli/redact"
	goredact "github.com/lastpersonlabs/goredact"
)

const fixturePath = "/Users/peytonmontei/Documents/entire/devenv/entireio/cli/.worktrees/support/cmd/entire/cli/transcript/compact/testdata/claude_full2.jsonl"

func loadFixture(tb testing.TB) []byte {
	tb.Helper()
	data, err := os.ReadFile(fixturePath)
	if err != nil {
		tb.Fatalf("read fixture: %v", err)
	}
	return data
}

// Our current production path: JSONL walk + 8 regex layers per leaf
// (betterleaks per leaf included).
func BenchmarkEntireJSONLBytes(b *testing.B) {
	data := loadFixture(b)
	b.ReportAllocs()
	b.SetBytes(int64(len(data)))
	for b.Loop() {
		if _, err := redact.JSONLBytes(data); err != nil {
			b.Fatal(err)
		}
	}
}

// Our raw-string path (no JSONL walk): one redact.String over the whole blob.
func BenchmarkEntireBytesRaw(b *testing.B) {
	data := loadFixture(b)
	b.ReportAllocs()
	b.SetBytes(int64(len(data)))
	for b.Loop() {
		_ = redact.Bytes(data)
	}
}

