// betterleaks: fragment setup paid once).
func BenchmarkBetterleaksWholeBlob(b *testing.B) {
	data := loadFixture(b)
	s := string(data)
	d, err := bldetect.NewDetectorDefaultConfig()
	if err != nil {
		b.Fatal(err)
	}
	b.ReportAllocs()
	b.SetBytes(int64(len(data)))
	for b.Loop() {
		_ = d.DetectString(s)
	}
}

// goredact balanced profile, streaming over the whole blob.
func BenchmarkGoredactBalanced(b *testing.B) {
	data := loadFixture(b)
